import json, sys

path = '/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d.jsonl'
terms = sys.argv[1:]

def get_text(obj):
    # try to extract a short text representation
    msg = obj.get('message')
    out = []
    if isinstance(msg, dict):
        content = msg.get('content')
        if isinstance(content, str):
            out.append(content)
        elif isinstance(content, list):
            for c in content:
                if isinstance(c, dict):
                    if c.get('type') == 'text':
                        out.append(c.get('text',''))
                    elif c.get('type') == 'tool_use':
                        out.append(f"[tool_use {c.get('name')}] input={json.dumps(c.get('input'))[:500]}")
                    elif c.get('type') == 'tool_result':
                        cont = c.get('content')
                        if isinstance(cont, list):
                            for cc in cont:
                                if isinstance(cc, dict) and cc.get('type')=='text':
                                    out.append(f"[tool_result] {cc.get('text','')[:500]}")
                        elif isinstance(cont, str):
                            out.append(f"[tool_result] {cont[:500]}")
    return "\n".join(out)

with open(path, 'r', errors='replace') as f:
    for i, line in enumerate(f):
        line=line.strip()
        if not line: continue
        low = line
        if any(t in low for t in terms):
            try:
                obj = json.loads(line)
            except Exception as e:
                continue
            ts = obj.get('timestamp','')
            typ = obj.get('type','')
            text = get_text(obj)
            # only print snippet containing term
            snippet = text[:800]
            print(f"--- line {i} ts={ts} type={typ} ---")
            print(snippet)
            print()
EOF
